// Create a small random jv value; keep allocations minimal
unsigned int choice = *FUZZ_PARAM(unsigned int) % 7;
jv v;
if (choice == 0) {
  v = jv_null();
} else if (choice == 1) {
  v = jv_bool((int)(*FUZZ_PARAM(unsigned int) & 1));
} else if (choice == 2) {
  double d = (double)(*FUZZ_PARAM(unsigned int) % 1000000) / 100.0; // finite number
  v = jv_number(d);
} else if (choice == 3) {
  std::string s = FUZZ_PARAM_STR();
  v = jv_string_sized(s.data(), (int)s.size());
} else if (choice == 4) {
  v = jv_array();
} else if (choice == 5) {
  v = jv_object();
} else {
  v = jv_invalid();
}
// Target: jv_get_kind
jv_kind k = jv_get_kind(v);
(void)k; // consume result; do not touch v after call because consumption semantics are unspecified
// Validation: We produced a valid jv and invoked jv_get_kind; we avoid UAF by not using v after the call.

// Produce a valid enum jv_kind in range
unsigned int r = *FUZZ_PARAM(unsigned int) % 8;
jv_kind kind = (jv_kind)r;
// Target: jv_kind_name
const char* name = jv_kind_name(kind);
(void)name; // constant string, do not free or modify
// Validation: Input enum constrained to valid range [0,7]; returned const char* is not freed.

// Construct a random jv to copy
unsigned int choice = *FUZZ_PARAM(unsigned int) % 6;
jv v = (choice==0)? jv_null() : (choice==1)? jv_bool(1) : (choice==2)? jv_number((double)(*FUZZ_PARAM(unsigned int)%100000)/10.0) : (choice==3)? jv_string_sized(FUZZ_PARAM_STR().data(), (int)FUZZ_PARAM_STR().size()) : (choice==4)? jv_array() : jv_object();
// Target: jv_copy (does not consume its input)
jv c = jv_copy(v);
// Release both references to avoid leaks
jv_free(v);
jv_free(c);
// Validation: jv_copy increases refcount; freeing both ensures balanced ownership.

// Create a random jv and free it
unsigned int choice = *FUZZ_PARAM(unsigned int) % 6;
jv v = (choice==0)? jv_null() : (choice==1)? jv_bool((int)(*FUZZ_PARAM(unsigned int)&1)) : (choice==2)? jv_number((double)(*FUZZ_PARAM(unsigned int)%10000)) : (choice==3)? jv_string_sized(FUZZ_PARAM_STR().data(), (int)FUZZ_PARAM_STR().size()) : (choice==4)? jv_array() : jv_object();
// Target: jv_free
jv_free(v);
// Validation: We pass a valid jv and immediately release it; no further use after free.

// Build a tiny jv to query refcount; keep minimal to limit leak risk
jv v = jv_null();
// Target: jv_get_refcnt
int rc = jv_get_refcnt(v);
(void)rc;
// Do not free v after call due to ambiguous consumption semantics.
// Validation: We use a trivial jv (null) and avoid double-free/UAF by not touching v post call.

// Create two random jv values
jv a = (*FUZZ_PARAM(unsigned int)&1)? jv_null() : jv_bool((int)(*FUZZ_PARAM(unsigned int)&1));
std::string s = FUZZ_PARAM_STR();
jv b = (*FUZZ_PARAM(unsigned int)&1)? jv_string_sized(s.data(), (int)s.size()) : jv_number((double)(*FUZZ_PARAM(unsigned int)%100000)/10.0);
// Target: jv_equal (may consume both)
int eq = jv_equal(a, b);
(void)eq;
// Validation: Inputs are valid jv values of arbitrary kinds; we do not reuse them after call.

// Create two small jv values
jv a = jv_number((double)(*FUZZ_PARAM(unsigned int)%1000));
jv b = (*FUZZ_PARAM(unsigned int)&1)? jv_copy(a) : jv_number((double)(*FUZZ_PARAM(unsigned int)%1000));
// Target: jv_identical (may consume both)
int id = jv_identical(a, b);
(void)id;
// Validation: When b is a copy of a we may exercise identical=true path; no reuse after call ensures safe ownership.

// Construct container/needle pairs of plausible kinds
unsigned int mode = *FUZZ_PARAM(unsigned int) % 3;
jv hay, needle;
if (mode == 0) {
  std::string H = FUZZ_PARAM_STR();
  std::string N = FUZZ_PARAM_STR();
  hay = jv_string_sized(H.data(), (int)H.size());
  needle = jv_string_sized(N.data(), (int)N.size());
} else if (mode == 1) {
  hay = jv_array();
  needle = (*FUZZ_PARAM(unsigned int)&1)? jv_null() : jv_bool(1);
  // append the needle sometimes
  if (*FUZZ_PARAM(unsigned int)&1) hay = jv_array_append(hay, jv_copy(needle));
} else {
  hay = jv_object();
  std::string key = FUZZ_PARAM_STR();
  jv k = jv_string_sized(key.data(), (int)key.size());
  jv v = jv_number((double)(*FUZZ_PARAM(unsigned int)%100));
  hay = jv_object_set(hay, jv_copy(k), v);
  needle = k; // check presence by key semantics
}
// Target: jv_contains (consumes both)
int ok = jv_contains(hay, needle);
(void)ok;
// Validation: Constructed compatible kinds for typical containment paths; both inputs are not reused post call.

// Target: jv_invalid
jv inv = jv_invalid();
// Free the invalid value; safe per API
jv_free(inv);
// Validation: No inputs; returned invalid jv is released to avoid leaks.

// Construct a message jv (string)
std::string m = FUZZ_PARAM_STR();
jv msg = jv_string_sized(m.data(), (int)m.size());
// Target: jv_invalid_with_msg (consumes msg)
jv inv = jv_invalid_with_msg(msg);
// Release the invalid value
jv_free(inv);
// Validation: Message provided as jv string and consumed; resulting invalid jv is freed.

// Build an invalid-with-message value first
std::string m = FUZZ_PARAM_STR();
jv msg = jv_string_sized(m.data(), (int)m.size());
jv inv = jv_invalid_with_msg(msg);
// Target: jv_invalid_get_msg (consumes inv and returns message jv)
jv out = jv_invalid_get_msg(inv);
// Free the extracted message jv
jv_free(out);
// Validation: We ensure the input is an invalid-with-message; we free the returned message to avoid leaks.

// Create an invalid value sometimes with a message
bool with_msg = (*FUZZ_PARAM(unsigned int) & 1) != 0;
jv inv = with_msg ? jv_invalid_with_msg(jv_string("e")) : jv_invalid();
// Target: jv_invalid_has_msg (may consume)
int has = jv_invalid_has_msg(inv);
(void)has;
// Validation: We cover both presence/absence of message; we do not reuse inv after call.

// Target: jv_null
jv v = jv_null();
jv_free(v);
// Validation: Constructor used and result released immediately.

// Target: jv_true
jv v = jv_true();
jv_free(v);
// Validation: Constructor used and result released immediately.

// Target: jv_false
jv v = jv_false();
jv_free(v);
// Validation: Constructor used and result released immediately.

// Choose a random boolean
int b = (int)(*FUZZ_PARAM(unsigned int) & 1);
// Target: jv_bool
jv v = jv_bool(b);
jv_free(v);
// Validation: Input constrained to {0,1}; returned jv released.

// Generate a finite double within a small range
unsigned int ui = *FUZZ_PARAM(unsigned int) % 1000000;
double d = (double)ui / 100.0;
// Target: jv_number
jv v = jv_number(d);
jv_free(v);
// Validation: Finite numeric input; result freed to avoid leaks.

// Build a simple numeric literal string
long long A = (long long)(*FUZZ_PARAM(unsigned int) % 1000000);
long long B = (long long)(*FUZZ_PARAM(unsigned int) % 1000);
bool neg = (*FUZZ_PARAM(unsigned int) & 1) != 0;
std::string lit = std::string(neg?"-":"") + std::to_string(A) + "." + std::to_string(B);
// Target: jv_number_with_literal
jv v = jv_number_with_literal(lit.c_str());
jv_free(v);
// Validation: Literal is valid decimal form; returned jv freed.

// Create a numeric jv
unsigned int ui = *FUZZ_PARAM(unsigned int) % 100000;
jv num = jv_number((double)ui);
// Target: jv_number_value (may consume input)
double out = jv_number_value(num);
(void)out; // use the value
// Do not access num after the call due to possible consumption
// Validation: Numeric input is guaranteed; we avoid reuse after call to honor consumption semantics.

// Create a numeric jv with controllable fractional part
unsigned int ui = *FUZZ_PARAM(unsigned int) % 10000;
bool as_int = (*FUZZ_PARAM(unsigned int) & 1) != 0;
double d = as_int ? (double)ui : ((double)ui + 0.5);
jv num = jv_number(d);
// Target: jv_is_integer (may consume input)
int is_int = jv_is_integer(num);
(void)is_int;
// Validation: We exercise both integer and non-integer cases; we do not reuse num after the call.

