jv num = jv_number(d);
// Target: jv_number_abs (consumes input, returns new number)
jv out = jv_number_abs(num);
// Release result to avoid leaks
jv_free(out);
// Validation: Provided a numeric jv; honored consumption by not reusing num; freed returned jv.

// Create a numeric jv and negate it (input consumed)
unsigned int ui = *FUZZ_PARAM(unsigned int) % 1000000;
double d = (double)ui / 100.0;
jv num = jv_number(d);
// Target: jv_number_negate (consumes input)
jv out = jv_number_negate(num);
// Release result
jv_free(out);
// Validation: Numeric precondition satisfied; avoided reuse of consumed input; freed output.

// Sometimes construct with a literal, sometimes without
bool with_lit = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
jv num = with_lit ? jv_number_with_literal("123.45") : jv_number(123.45);
// Target: jv_number_has_literal (may consume input)
int has = jv_number_has_literal(num);
(void)has;
// Do not reuse num after the call due to possible consumption
// Validation: Covered both literal/no-literal; respected consumption semantics.

// Ensure a numeric jv with a stored literal
std::string lit = std::string("-") + std::to_string((int)(*FUZZ_PARAM(unsigned int)%10000)) + "." + std::to_string((int)(*FUZZ_PARAM(unsigned int)%100));
jv num = jv_number_with_literal(lit.c_str());
// To guard against possible consumption while keeping the storage alive, pass a copied handle
jv handle = jv_copy(num);
// Target: jv_number_get_literal
const char* p = jv_number_get_literal(handle);
// We expect a non-null pointer since we created with a literal
FUZZ_ASSERT(p != nullptr, "number with literal must yield non-null literal pointer");
// Use the pointer briefly (no modification); then free the original to balance refs
jv_free(num);
// Validation: Passing a copy preserves the underlying storage even if consumed; we assert pointer non-null and avoid UAF.

// Target: jv_array
jv arr = jv_array();
