// Target: jv_array_append (consumes both)
jv out = jv_array_append(arr, val);
// Free result
jv_free(out);
// Validation: Proper ownership handling; freed returned array.

// Create two arrays with a few elements
jv a = jv_array();
int n1 = (int)(*FUZZ_PARAM(unsigned int) % 3);
for (int i = 0; i < n1; i++) a = jv_array_append(a, jv_number((double)i));

jv b = jv_array();
