// Create an array with several elements
jv arr = jv_array();
int n = 1 + (int)(*FUZZ_PARAM(unsigned int) % 6);
for (int i = 0; i < n; i++) arr = jv_array_append(arr, jv_number((double)(i * 3)));
// Choose start/end within [0, n]
int start = (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)(n + 1));
