// Target: jv_string_empty
jv j = jv_string_empty(cap);
// Free
jv_free(j);
// Validation: Non-negative hint respected; freed result.

// Build a jv string from fuzz data
std::string s = FUZZ_PARAM_STR();
jv j = jv_string_sized(s.data(), (int)s.size());
// Target: jv_string_length_bytes (may consume input)
int bytes = jv_string_length_bytes(j);
(void)bytes;
// Do not reuse j after call
