jv j = jv_string_sized(s.data(), (int)s.size());
// Target: jv_string_length_codepoints (may consume input)
int cps = jv_string_length_codepoints(j);
(void)cps;
// Validation: Proper string input; avoided reuse due to possible consumption.

// Build a jv string to hash
std::string s = FUZZ_PARAM_STR();
jv j = jv_string_sized(s.data(), (int)s.size());
// Target: jv_string_hash (may consume input)
unsigned long hv = jv_string_hash(j);
(void)hv;
// Validation: Passed a string; honored possible consumption.

// Build a jv string and keep it alive while accessing internal buffer
std::string s = FUZZ_PARAM_STR();
jv j = jv_string_sized(s.data(), (int)s.size());
// Pass a copied handle in case the accessor consumes its input
jv handle = jv_copy(j);
// Target: jv_string_value
const char* p = jv_string_value(handle);
FUZZ_ASSERT(p != nullptr, "jv_string_value must return non-null for a valid string");
// Now release the original reference; the underlying storage remains alive due to the copied handle passed to the accessor
jv_free(j);
// Validation: Ensured non-null pointer and avoided UAF by passing a copied handle and freeing the original afterwards.

// Build two jv strings from fuzz data (both may be consumed)
std::string S = FUZZ_PARAM_STR();
std::string K = FUZZ_PARAM_STR();
jv j = jv_string_sized(S.data(), (int)S.size());
jv k = jv_string_sized(K.data(), (int)K.size());
// Target: jv_string_indexes (consumes both strings)
jv idxs = jv_string_indexes(j, k);
// Free returned array of positions
jv_free(idxs);
// Validation: Provided valid string inputs; freed returned jv array. Inputs not reused after call.

// Create a jv string from fuzz data
std::string S = FUZZ_PARAM_STR();
int len = (int)S.size();
// Choose start/end within [0, len]
int start = (len == 0) ? 0 : (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)(len + 1));
int end   = (len == 0) ? 0 : (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)(len + 1));
if (end < start) { int t = start; start = end; end = t; }
// Build the jv string and slice
jv j = jv_string_sized(S.data(), len);
// Target: jv_string_slice (may consume input)
jv sub = jv_string_slice(j, start, end);
// Free the result
jv_free(sub);
// Validation: start/end non-negative and bounded; avoided reuse of possibly consumed input; freed output.

// Build two strings to concatenate
std::string A = FUZZ_PARAM_STR();
std::string B = FUZZ_PARAM_STR();
// Keep sizes modest to limit allocations
if (A.size() > 1024) A.resize(1024);
if (B.size() > 1024) B.resize(1024);
jv a = jv_string_sized(A.data(), (int)A.size());
jv b = jv_string_sized(B.data(), (int)B.size());
// Target: jv_string_concat (consumes both)
jv out = jv_string_concat(a, b);
// Free concatenated result
jv_free(out);
// Validation: Proper string inputs; honored consumption; freed output.

// Use a fixed, safe printf-style format and matching arguments
int x = (int)(*FUZZ_PARAM(unsigned int) % 100000);
std::string s = FUZZ_PARAM_STR();
if (s.size() > 64) s.resize(64); // keep it small
// Target: jv_string_fmt
jv out = jv_string_fmt("num=%d str=%s", x, s.c_str());
// Free the formatted string
jv_free(out);
// Validation: Format string and arguments are consistent; freed returned jv.

// Create base string
std::string S = FUZZ_PARAM_STR();
if (S.size() > 128) S.resize(128); // keep small
jv a = jv_string_sized(S.data(), (int)S.size());
// Generate a valid Unicode scalar value (exclude surrogates)
unsigned int r = *FUZZ_PARAM(unsigned int) % (0x110000); // 0..0x10FFFF inclusive bound
uint32_t c = (uint32_t)r;
if (c >= 0xD800 && c <= 0xDFFF) { c = 0x20; } // map surrogates to space
// Target: jv_string_append_codepoint (consumes string)
jv out = jv_string_append_codepoint(a, c);
// Free result
jv_free(out);
// Validation: Ensured codepoint is a valid Unicode scalar; honored consumption; freed output.

// Base jv string
std::string base = FUZZ_PARAM_STR();
if (base.size() > 128) base.resize(128);
jv a = jv_string_sized(base.data(), (int)base.size());
// Buffer to append
std::string buf = FUZZ_PARAM_STR();
if (buf.size() > 256) buf.resize(256);
int len = (int)buf.size();
if (len < 0) { FUZZ_BAIL(); }
const char* p = len > 0 ? buf.data() : ""; // non-null if len>0
// Target: jv_string_append_buf (consumes string)
jv out = jv_string_append_buf(a, p, len);
// Free result
jv_free(out);
// Validation: Enforced non-negative len and non-null when len>0; honored consumption; freed output.

// Base jv string
std::string base = FUZZ_PARAM_STR();
if (base.size() > 128) base.resize(128);
jv a = jv_string_sized(base.data(), (int)base.size());
// C string to append (NUL-terminated)
std::string add = FUZZ_PARAM_STR();
if (add.size() > 256) add.resize(256);
// Target: jv_string_append_str (consumes base string)
jv out = jv_string_append_str(a, add.c_str());
// Free result
jv_free(out);
// Validation: Passed a valid C string; honored consumption; freed output.

// Base string to repeat
std::string S = FUZZ_PARAM_STR();
if (S.size() > 64) S.resize(64); // keep total allocation bounded
jv j = jv_string_sized(S.data(), (int)S.size());
// Choose small non-negative repeat count
int n = (int)(*FUZZ_PARAM(unsigned int) % 16);
// Target: jv_string_repeat (consumes input)
jv out = jv_string_repeat(j, n);
// Free result
jv_free(out);
// Validation: n >= 0 and bounded to keep allocations small; honored consumption; freed output.

// Two strings: haystack and separator
std::string H = FUZZ_PARAM_STR();
std::string Sep = FUZZ_PARAM_STR();
if (H.size() > 1024) H.resize(1024);
if (Sep.size() > 64) Sep.resize(64);
jv j = jv_string_sized(H.data(), (int)H.size());
jv sep = jv_string_sized(Sep.data(), (int)Sep.size());
// Target: jv_string_split (consumes both)
jv arr = jv_string_split(j, sep);
// Free returned array
jv_free(arr);
// Validation: Provided valid string inputs; freed output; inputs not reused post-consumption.

// Build a jv string
std::string S = FUZZ_PARAM_STR();
if (S.size() > 512) S.resize(512);
jv j = jv_string_sized(S.data(), (int)S.size());
// Target: jv_string_explode (consumes input)
jv arr = jv_string_explode(j);
// Free resulting array of codepoints/characters
jv_free(arr);
// Validation: Proper string input; honored consumption; freed output.

// Construct a valid array of codepoints by exploding a string first
std::string S = FUZZ_PARAM_STR();
if (S.size() > 256) S.resize(256);
