import random
import json
import math
from typing import Any, List, Dict, Tuple

# JSON text generator for exercising jq/jv parsers.
# Goals:
# - Produce valid JSON for both NUL-terminated (c_str) and sized-buffer parsers
# - Stay under 1024 bytes commonly, and always under 4096 bytes
# - Cover variety: objects, arrays, numbers (ints/floats, exponents), strings
# - Include edge cases: empty structures, deep nesting (but modest), unicode, escapes
# - Deterministic per-seed, but with variety across seeds

MAX_TOTAL_BYTES = 4096
TARGET_MAX = 1024  # fuzz stubs cap input to 1024 bytes

UNICODE_SAMPLES = [
    "",  # allow empty fragments
    "π",
    "𝄞",  # surrogate pair
    "汉字",
    "😀",
    "ñö",
    "Ω≈ç√∫˜µ≤≥÷",
    "مرحبا",
    "こんにちは",
    "Здра́вствуйте",
]

ESCAPE_FRAGMENTS = [
    "\\\\",  # backslash
    "\"",      # quote
    "\\n",
    "\\r",
    "\\t",
    "/",
]

KEY_WORDS = [
    "a", "b", "key", "value", "number", "list", "map", "true", "false",
    "null", "data", "unicode", "escape", "nested", "id", "name", "description"
]

# Number builders

def rand_int(r: random.Random) -> int:
    # Mix small and large magnitudes
    choices = [0, 1, -1, 2**31-1, -2**31, 2**53-1, -(2**53-1)]
    if r.random() < 0.6:
        return r.randint(-10_000, 10_000)
    return r.choice(choices)

def rand_float(r: random.Random) -> float:
    mode = r.random()
    if mode < 0.4:
        # simple decimal
        return r.uniform(-1e6, 1e6)
    elif mode < 0.7:
        # exponent
        base = r.uniform(-1e3, 1e3)
        exp = r.randint(-12, 12)
        return base * (10 ** exp)
    else:
        # rational-like
        num = r.randint(-10_000, 10_000)
        den = r.randint(1, 10_000)
        return num / den

def number_literal(r: random.Random) -> str:
    # Construct a numeric literal with optional exponent and sign, or integer
    if r.random() < 0.55:
        n = rand_int(r)
        return str(n)
    # float literal formatting
    x = rand_float(r)
    # Prefer JSON-compatible formatting without NaN/Inf
    if math.isinf(x) or math.isnan(x):
        x = 0.0
    fmt_choice = r.random()
    if fmt_choice < 0.4:
        s = f"{x:.6f}".rstrip("0").rstrip(".")
    elif fmt_choice < 0.8:
        s = f"{x:.8g}"
    else:
        # force exponent form sometimes
        mant = x
        if mant == 0:
            s = "0e0"
        else:
            s = ("%e" % mant)
    # Ensure it parses as JSON number (no leading '+')
    if s.startswith('+'):
        s = s[1:]
    # Strip leading zeros on integers like 00012 (invalid JSON number)
    try:
        # If s represents an int, normalize
        if all(c in "-0123456789" for c in s):
            s = str(int(s))
    except Exception:
        pass
    return s

# String builders

def rand_codepoint(r: random.Random) -> str:
    # Choose from curated samples or random BMP/non-BMP scalar
    if r.random() < 0.7:
        return r.choice(UNICODE_SAMPLES)
    # Random Unicode scalar value excluding surrogates
    while True:
        cp = r.randint(0, 0x10FFFF)
        if 0xD800 <= cp <= 0xDFFF:
            continue
        try:
            return chr(cp)
        except ValueError:
            continue

def rand_string(r: random.Random, max_len: int = 40) -> str:
    # Build a UTF-8 friendly string with escapes and unicode
    parts: List[str] = []
    n = r.randint(0, max(1, max_len))
    for _ in range(n):
        t = r.random()
        if t < 0.15:
            parts.append(r.choice(ESCAPE_FRAGMENTS))
        elif t < 0.65:
            # printable ascii excluding quotes/backslash to minimize escaping
            c = r.randint(32, 126)
            if c in (34, 92):  # quote or backslash
                parts.append("\\" + chr(c))
            else:
                parts.append(chr(c))
        else:
            parts.append(rand_codepoint(r))
    raw = "".join(parts)
    # Ensure valid JSON string by using json.dumps for escaping
    return json.loads(json.dumps(raw))  # round-trip to normalize

def json_string_literal(r: random.Random, max_len: int = 40) -> str:
    s = rand_string(r, max_len)
    return json.dumps(s, ensure_ascii=False)

# JSON value builders

def make_boolean(r: random.Random) -> str:
    return "true" if r.random() < 0.5 else "false"

def make_null() -> str:
    return "null"

def make_number(r: random.Random) -> str:
    return number_literal(r)

def make_string(r: random.Random, max_len: int = 40) -> str:
    return json_string_literal(r, max_len)

def make_array(r: random.Random, depth: int, budget: int) -> str:
    # Build array with elements while not exceeding budget
    n = r.randint(0, 8 if depth < 2 else 4)
    elems: List[str] = []
    for _ in range(n):
        if budget <= 2:
            break
        v = make_value(r, depth+1, budget)
        elems.append(v)
        budget -= len(v) + 1
    return "[" + ",".join(elems) + "]"

def make_object(r: random.Random, depth: int, budget: int) -> str:
    n = r.randint(0, 8 if depth < 2 else 4)
    pairs: List[str] = []
    # include some typical and some random keys
    for _ in range(n):
        if budget <= 4:
            break
        if r.random() < 0.5:
            key = r.choice(KEY_WORDS)
        else:
            key = rand_string(r, max_len=16)
        k = json.dumps(key, ensure_ascii=False)
        v = make_value(r, depth+1, budget)
        pairs.append(f"{k}:{v}")
        budget -= len(k) + len(v) + 2
    return "{" + ",".join(pairs) + "}"

def make_value(r: random.Random, depth: int, budget: int) -> str:
    # Choose type with weights; limit depth
    if depth > 4:
        # prefer terminals at depth
        choices = [make_string, make_number, make_boolean, lambda rr: make_null()]
        f = r.choice(choices)
        if f is make_string:
            return f(r, max_len=24)
        elif f is make_number or f is make_boolean:
            return f(r)
        else:
            return f(r)  # type: ignore
    pick = r.random()
    if pick < 0.20:
        return make_string(r, max_len=48)
    elif pick < 0.40:
        return make_number(r)
    elif pick < 0.50:
        return make_boolean(r)
    elif pick < 0.55:
        return make_null()
    elif pick < 0.78:
        return make_array(r, depth, budget)
    else:
        return make_object(r, depth, budget)

def make_top_level(r: random.Random, target_max: int) -> str:
    # Sometimes produce a single value, sometimes a concatenation of multiple JSON texts
    # because incremental parsers may handle streams.
    mode = r.random()
    if mode < 0.65:
        doc = make_value(r, 0, target_max)
        # Ensure it fits
        return doc[:target_max]
    else:
        # JSON stream: multiple values separated by whitespace/newlines
        parts: List[str] = []
        remaining = target_max
        count = r.randint(2, 6)
        for i in range(count):
            if remaining < 4:
                break
            v = make_value(r, 0, remaining)
            if len(v) + 1 > remaining:
                break
            parts.append(v)
            ws = "\n" if r.random() < 0.5 else " "
            parts.append(ws)
            remaining -= len(v) + len(ws)
        if not parts:
            parts.append(make_value(r, 0, target_max))
        s = "".join(parts).strip()
        return s[:target_max]

def ensure_size_bounds(s: str) -> str:
    # Hard cap to keep under fuzz stub truncation and global limit
    if len(s) > TARGET_MAX:
        s = s[:TARGET_MAX]
    if len(s) > MAX_TOTAL_BYTES:
        s = s[:MAX_TOTAL_BYTES]
    return s

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Bias to sometimes produce very small or edge-case documents
    special = r.random()
    if special < 0.08:
        doc = "{}"
    elif special < 0.16:
        doc = "[]"
    elif special < 0.22:
        doc = "\"\""
    elif special < 0.28:
        doc = "0"
    elif special < 0.34:
        # unicode-only string
        doc = json.dumps(r.choice(UNICODE_SAMPLES), ensure_ascii=False)
    else:
        doc = make_top_level(r, TARGET_MAX)
    doc = ensure_size_bounds(doc)
    # Ensure valid UTF-8 bytes; json text must be UTF-8; Python str is Unicode; encode to UTF-8
    b = doc.encode('utf-8')
    # Guarantee NUL-terminated usability by appending nothing; C++ fuzzer uses std::string which adds NUL for c_str()
    # For sized parser, raw bytes are used as-is.
    # Keep size under global cap
    if len(b) > MAX_TOTAL_BYTES:
        b = b[:MAX_TOTAL_BYTES]
    return b

import random
import json
from typing import List

# Generate valid UTF-8 JSON for jv_load_file. Ensure no surrogate code points appear.
# Limit output to <=4096 bytes.

MAX_BYTES = 4096

ESCAPE_SAMPLE = [
    "\\\"",  # escaped quote
    "\\n",
    "\\r",
    "\\t",
    "\\b",
    "\\f",
    "\\\\",
]

# Avoid isolated surrogates; include only valid Unicode scalar values
UNICODE_SAMPLE = [
    "\u0000", "\u0008", "\u0009", "\u000A", "\u000D",
    "\u007F", "\u00A9", "\u03B1", "\u0416", "\u20AC",
    "\u2603", "\u2764", "\U0001D11E",  # Musical Symbol G Clef
]

ASCII_WORDS = [
    "foo", "bar", "baz", "qux", "alpha", "beta", "gamma", "delta",
    "key", "value", "name", "id", "enabled", "count", "items",
]

COLOR_SPECS = [
    "0,1,2,3,4,5,6,7",
    "bright:0,1,2,3,4,5,6,7",
    "fg=2;bg=5",
]


def rnd(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)


def rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))


def rand_float(r: random.Random) -> float:
    choices = [
        0, 1, -1, 2**31 - 1, -(2**31), 2**53 - 1, -(2**53 - 1),
        r.uniform(-1e12, 1e12), r.random(), -r.random(),
    ]
    return r.choice(choices)


def rand_number_literal(r: random.Random) -> str:
    style = r.randrange(6)
    n = rand_float(r)
    if style == 0:
        return str(int(n))
    if style == 1:
        return f"{n:.{rnd(r,0,6)}f}"
    if style == 2:
        base = r.uniform(0.0001, 999999.0) * (-1 if rand_bool(r) else 1)
        exp = rnd(r, -12, 12)
        # Ensure exponent form
        return f"{base:.{rnd(r,0,6)}e}".split('e')[0] + f"e{exp}"
    if style == 3:
        return ("-" if rand_bool(r) else "") + str(rnd(r,0,1)) + "." + ("0"*rnd(r,0,4)) + str(rnd(r,0,999))
    if style == 4:
        return "0" if rand_bool(r) else "0.0"
    return str(n)


def _safe_ascii_chunk(r: random.Random, max_len: int) -> str:
    # Generate ASCII without control chars to avoid accidental surrogates or invalids
    chunk_len = rnd(r, 1, max(1, min(8, max_len)))
    return ''.join(chr(r.randrange(32, 127)) for _ in range(chunk_len))


def rand_string(r: random.Random, max_len: int = 64) -> str:
    parts: List[str] = []
    # The parts are chosen from safe sets only
    steps = rnd(r, 0, max(0, max_len // 2 + 1))
    while steps > 0 and len(''.join(parts)) < max_len:
        pick = r.randrange(5)
        if pick == 0:
            parts.append(r.choice(ASCII_WORDS))
        elif pick == 1:
            parts.append(r.choice(ESCAPE_SAMPLE))
        elif pick == 2:
            parts.append(r.choice(UNICODE_SAMPLE))
        elif pick == 3:
            parts.append(_safe_ascii_chunk(r, max_len))
        else:
            parts.append(r.choice(["-", "_", ".", ":", "/", ",", "@"]))
        steps -= 1
    s = ''.join(parts)
    # Ensure no surrogate code points sneak in
    s = s.encode('utf-8', 'strict').decode('utf-8', 'strict')
    return s


def make_primitive(r: random.Random):
    kind = r.randrange(6)
    if kind == 0:
        return None
    if kind == 1:
        return True if rand_bool(r) else False
    if kind == 2:
        lit = rand_number_literal(r)
        try:
            if '.' in lit or 'e' in lit or 'E' in lit:
                return float(lit)
            return int(lit)
        except Exception:
            return r.uniform(-1e6, 1e6)
    if kind == 3:
        return rand_string(r, 32)
    if kind == 4:
        return [make_primitive(r) for _ in range(rnd(r, 0, 5))]
    obj = {}
    for _ in range(rnd(r, 0, 5)):
        key = rand_string(r, 16) or f"k{rnd(r,0,999)}"
        obj[key] = make_primitive(r)
    return obj


def make_deep_json(r: random.Random, depth: int = 0):
    if depth > 4:
        return make_primitive(r)
    typ = r.randrange(5)
    if typ == 0:
        size = rnd(r, 1, 6)
        o = {}
        for _ in range(size):
            key = rand_string(r, 24) or f"k{rnd(r,0,999)}"
            o[key] = make_deep_json(r, depth + 1)
        return o
    if typ == 1:
        size = rnd(r, 0, 8)
        return [make_deep_json(r, depth + 1) for _ in range(size)]
    if typ == 2:
        return {
            "name": rand_string(r, 20),
            "count": rnd(r, -5, 20),
            "enabled": rand_bool(r),
            "values": [make_primitive(r) for _ in range(rnd(r, 1, 6))],
            "meta": {"colors": r.choice(COLOR_SPECS), "ratio": rand_number_literal(r)},
        }
    if typ == 3:
        return rand_string(r, 64)
    return make_primitive(r)


def assemble_document(r: random.Random) -> str:
    choice = r.randrange(7)
    if choice == 0:
        return json.dumps(make_deep_json(r), ensure_ascii=False)
    if choice == 1:
        arr = [make_primitive(r) for _ in range(rnd(r, 5, 40))]
        return json.dumps(arr, ensure_ascii=False)
    if choice == 2:
        obj = {
            "id": rnd(r, 0, 1_000_000),
            "name": rand_string(r, 40),
            "tags": [rand_string(r, 12) for _ in range(rnd(r, 0, 10))],
            "config": {
                "retry": rnd(r, 0, 10),
                "timeout_ms": rnd(r, 0, 100000),
                "features": {w: rand_bool(r) for w in r.sample(ASCII_WORDS, k=rnd(r, 1, min(6, len(ASCII_WORDS))))},
            },
            "data": [make_deep_json(r) for _ in range(rnd(r, 1, 6))],
        }
        return json.dumps(obj, ensure_ascii=False)
    if choice == 3:
        s = "".join([r.choice([rand_string(r, 8), r.choice(ESCAPE_SAMPLE), r.choice(UNICODE_SAMPLE)]) for _ in range(rnd(r, 1, 20))])
        s = s.encode('utf-8', 'strict').decode('utf-8', 'strict')
        return json.dumps(s, ensure_ascii=False)
    if choice == 4:
        nums = []
        for _ in range(rnd(r, 5, 50)):
            lit = rand_number_literal(r)
            try:
                v = float(lit) if any(c in lit for c in ".eE") else int(lit)
            except Exception:
                v = rand_float(r)
            nums.append(v)
        return json.dumps(nums, ensure_ascii=False)
    if choice == 5:
        seq = [r.choice([True, False, None]) for _ in range(rnd(r, 5, 60))]
        return json.dumps(seq, ensure_ascii=False)
    mixed = [make_deep_json(r) for _ in range(rnd(r, 3, 10))]
    return json.dumps(mixed, ensure_ascii=False)


def clamp_bytes(s: str) -> bytes:
    # Always strict-encode; if any surrogate sneaks in, this will raise. We guard callers to avoid that.
    b = s.encode('utf-8', 'strict')
    if len(b) <= MAX_BYTES:
        return b
    # Try compact formatting first
    try:
        v = json.loads(s)
        compact = json.dumps(v, separators=(',', ':'), ensure_ascii=False).encode('utf-8', 'strict')
        if len(compact) <= MAX_BYTES:
            return compact
        # Reduce arrays/objects to fit
        if isinstance(v, list) and len(v) > 0:
            # Keep proportional prefix
            k = max(1, int(len(v) * MAX_BYTES / max(1, len(compact))))
            sub = v[:k]
            compact2 = json.dumps(sub, separators=(',', ':'), ensure_ascii=False).encode('utf-8', 'strict')
            if len(compact2) <= MAX_BYTES:
                return compact2
        if isinstance(v, dict) and len(v) > 0:
            keys = list(v.keys())
            k = max(1, int(len(keys) * MAX_BYTES / max(1, len(compact))))
            sub = {kk: v[kk] for kk in keys[:k]}
            compact2 = json.dumps(sub, separators=(',', ':'), ensure_ascii=False).encode('utf-8', 'strict')
            if len(compact2) <= MAX_BYTES:
                return compact2
    except Exception:
        pass
    # Final safe fallback: return minimal valid JSON
    return b"null"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    include_bom = r.random() < 0.1
    doc = assemble_document(r)
    # Ensure no surrogates
    doc = doc.encode('utf-8', 'strict').decode('utf-8', 'strict')
    out = clamp_bytes(doc)
    if include_bom and len(out) + 3 <= MAX_BYTES:
        out = b"\xEF\xBB\xBF" + out
    return out
